function Login(){const{user,refresh}=useAuth(),nav=useNavigate(),[form,setForm]=useState({username:'',password:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);if(user)return <Navigate to="/valves"/>;const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await api('/auth/login',{method:'POST',body:JSON.stringify(form)});(document.activeElement as HTMLElement|null)?.blur();await refresh();nav('/valves')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};return <div className="login"><div className="login-theme"><ThemeToggle/></div><div className="login-art"><div className="login-brand"><img src={logoPath} alt="CVS Controls"/><span>Valve Database Viewer</span></div><div className="art-lines"/></div><form className="login-card" onSubmit={submit}><span className="eyebrow">Valve Database Login</span><h2>Welcome back</h2><p>Sign in with an account.</p>{error&&<Notice type="error">{error}</Notice>}<label>Email<input type="email" required autoComplete="username" value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Password<input type="password" required autoComplete="current-password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><button className="primary" disabled={busy}>{busy?'Signing in…':'Sign in'}</button></form></div>}
