function ToleranceEditor({value,onChange,onSave,saved,busy}:any){const fields=[['mountingTolerance','Mounting dimensions','in'],['packingGridTolerance','Packing / grid','in'],['angleTolerance','Angles','°'],['squareTolerance','Actuator square','in']];return <details className="tolerance-editor card"><summary><span><Settings2/>Configurator tolerances</span><small>Admins only</small></summary><div className="tolerance-fields">{fields.map(([key,label,unit])=><label key={key}>{label}<span><input type="number" min="0" step="0.001" value={value[key]} onChange={e=>onChange({...value,[key]:e.target.value})}/><b>{unit}</b></span></label>)}</div><div className="tolerance-footer"><small>{saved||'Controls how close dimensions must be to count as a match.'}</small><button className="primary compact" disabled={busy} onClick={onSave}>Save tolerances</button></div></details>}
