function DetailSection({section,fields,data}:any){const visible=fields.filter((f:any)=>present(data[fieldMap[f.field_key]]));if(!visible.length)return null;return <section className="card detail-section"><div className="section-title"><h3>{section.label}</h3><span>{visible.length} fields</span></div><dl>{visible.map((f:any)=>{let v=data[fieldMap[f.field_key]];if(typeof v==='number'&&f.decimal_places!=null)v=v.toFixed(f.decimal_places);const stemClass=f.field_key==='valve.stem_type'?`stem-value ${String(v).toLowerCase()}`:'';return <div className={f.is_highlighted?'highlight':''} key={f.id} title={f.help_text||''}><dt>{f.label}</dt><dd className={stemClass}>{`${v}${f.unit?` ${f.unit}`:''}`}</dd></div>})}</dl></section>}
const summaryValues:Record<string,(data:any)=>any>={'summary.last_drawing_created':data=>formatTimestamp(data.lastManufacturedTimestamp),'summary.last_job':data=>data.lastJobNumber,'summary.last_quantity':data=>data.lastQuantity,'summary.configuration':data=>data.lastConfigurationName,'summary.fusion_document':data=>data.lastFusionDocument,'summary.actuator':data=>data.lastActuator,'summary.last_bracket':data=>data.lastBracket||'----','summary.total_runs':data=>data.totalManufacturingRuns};
