function History({rows,current}:any){const[expanded,setExpanded]=useState<number|null>(null),columns=[['timestamp','Drawing created'],['job_number','Job'],['quantity','Qty'],['configuration_name','Configuration'],['fusion_document_name','Fusion document'],['actuator_name','Actuator']].filter(([key])=>rows.some((r:any)=>present(r[key]))),showIdentity=rows.some((r:any)=>['valve_brand','valve_size','valve_class','valve_model','valve_port'].some(key=>present(r[key]))),columnCount=1+columns.length+(showIdentity?1:0);return <section className="card table-card"><div className="section-title"><h3>Configurator &amp; drawing history</h3><span>Newest first</span></div>{!rows.length?<div className="empty-small">No configurator or drawing history is recorded for this valve.</div>:<div className="table-wrap"><table><thead><tr><th/>{columns.map(([,label])=><th key={label}>{label}</th>)}{showIdentity&&<th>Historical valve</th>}</tr></thead><tbody>{rows.map((r:any)=><React.Fragment key={r.id}><tr className="clickable" onClick={()=>setExpanded(expanded===r.id?null:r.id)}><td>{expanded===r.id?<ChevronDown size={16}/>:<ChevronRight size={16}/>}</td>{columns.map(([key])=><td key={key}>{key==='timestamp'?formatTimestamp(r[key]):r[key]}</td>)}{showIdentity&&<td>{[r.valve_brand,r.valve_size,present(r.valve_class)?`Class ${r.valve_class}`:null,r.valve_model,r.valve_port].filter(present).join(' · ')}{mismatch(r,current)&&<span className="warn-tag">Snapshot differs</span>}</td>}</tr>{expanded===r.id&&<tr className="expanded"><td colSpan={columnCount}><div className="parameter-grid">{Object.entries(r).filter(([k,v])=>present(v)&&!['id','valve_id'].includes(k)).map(([k,v])=><div key={k}><span>{friendly(k)}</span><strong>{String(v)}</strong></div>)}</div></td></tr>}</React.Fragment>)}</tbody></table></div>}</section>}
const mismatch=(r:any,v:any)=>r.valve_brand!==v.valve_brand||r.valve_size!==v.valve_size||r.valve_class!==v.valve_class||r.valve_model!==v.valve_model_number;const friendly=(x:string)=>x.replaceAll('_',' ').replace(/\b(id|od|bhc|scha)\b/gi,m=>m.toUpperCase()).replace(/\b\w/g,m=>m.toUpperCase());function formatTimestamp(v:any){if(!v)return null;if(!/^\d{4}-\d\d-\d\d \d\d:\d\d:\d\d$/.test(v))return `${v} (invalid)`;const d=new Date(v.replace(' ','T'));return Number.isNaN(d.getTime())?`${v} (invalid)`:d.toLocaleString()}

function Dashboard(){const[d,setD]=useState<any>(),[error,setError]=useState('');useEffect(()=>{api('/admin/dashboard').then(setD).catch(e=>setError(e.message))},[]);if(error)return <Notice type="error">{error}</Notice>;if(!d)return <Splash/>;const cards=[['Valves',d.valveCount],['Keyed stems',d.keyedStemCount],['Flat stems',d.flatStemCount],['Manufacturing rows',d.manufacturingRows],['Matched rows',d.matchedManufacturingRows],['Unmatched rows',d.unmatchedManufacturingRows],['Valves with history',d.valvesWithHistory],['Never manufactured',d.valvesNeverManufactured],['Identity mismatches',d.historicalIdentityMismatches],['Actuator sets',d.actuatorSetCount],['Bracket patterns',d.bracketPatternCount],['Universal adapters',d.universalAdapterCount],['Active users',d.activeUsers]];return <><section className="intro"><div><span className="eyebrow">System overview</span><h2>Administration dashboard</h2><p>Live counts across the active source databases and Supabase application records.</p></div><span className={`pill ${d.status}`}>{d.status==='complete'?'Cross-validation complete':'Cross-validation pending'}</span></section><div className="stat-grid">{cards.map(([k,v])=><div className="stat card" key={k}><span>{k}</span><strong>{v??'—'}</strong></div>)}</div><div className="two-col"><section className="card"><div className="section-title"><h3>Latest upload</h3></div>{d.latestUpload?<p><strong>{friendly(d.latestUpload.source_type)}</strong><br/>{d.latestUpload.original_file_name}<br/><small>{formatTimestamp(d.latestUpload.uploaded_at)}</small></p>:<p className="muted">No databases uploaded yet.</p>}</section><section className="card"><div className="section-title"><h3>Recent activity</h3></div><ul className="activity-list">{d.recentAudit.map((x:any)=><li key={x.id}><span>{friendly(x.action)}</span><small>{x.username||'System'} · {formatTimestamp(x.created_at)}</small></li>)}</ul></section></div></>}
function Databases(){const[items,setItems]=useState<any[]>([]),[cross,setCross]=useState<any>(),[busy,setBusy]=useState(''),[error,setError]=useState('');const load=()=>Promise.all([api('/admin/database-sources'),api('/admin/database-sources/cross-validation')]).then(([a,b])=>{setItems(a);setCross(b)});useEffect(()=>{load().catch(e=>setError(e.message))},[]);const send=async(type:string,file:File)=>{setBusy(type);setError('');const fd=new FormData();fd.append('database',file);try{await api(`/admin/database-sources/${type==='hardware_configurator'?'hardware-configurator':'manufacturing-log'}/upload`,{method:'POST',body:fd});await load()}catch(e){setError((e as Error).message)}finally{setBusy('')}};return <>{error&&<Notice type="error">{error}</Notice>}<section className="intro"><div><span className="eyebrow">Source control</span><h2>Database management</h2><p>Uploads are opened in isolation, integrity checked, schema validated, and only then activated.</p></div></section><div className="two-col">{[['hardware_configurator','Hardware Configurator Database'],['manufacturing_log','Manufacturing Log Database']].map(([type,title])=>{const row=items.find(x=>x.source_type===type);return <section className="card upload-card" key={type}><div className="db-icon"><Database/></div><h3>{title}</h3><p className="muted">{row?`${row.original_file_name} · ${formatBytes(row.file_size_bytes)}`:'No active database'}</p><div className="source-meta"><span>Status <b className={row?.validation_status==='valid'?'good':''}>{row?.validation_status||'Not uploaded'}</b></span><span>Uploaded <b>{formatTimestamp(row?.uploaded_at)||'—'}</b></span></div><label className="upload-button">{busy===type?'Validating…':row?'Replace database':'Choose database'}<input type="file" accept=".db,.sqlite,.sqlite3" disabled={!!busy} onChange={e=>e.target.files?.[0]&&send(type,e.target.files[0])}/></label>{row?.validationReport&&<ValidationReport report={row.validationReport}/>}</section>})}</div>{cross&&<section className="card cross"><div className="section-title"><h3>Cross-database validation</h3><span className={`pill ${cross.status}`}>{cross.status}</span></div>{cross.status==='pending'?<p className="muted">{cross.message}</p>:<div className="summary-grid">{Object.entries(cross).filter(([k])=>k!=='status').map(([k,v])=><div key={k}><span>{friendly(k)}</span><strong>{String(v)}</strong></div>)}</div>}</section>}</>}
function ValidationReport({report}:any){return <details className="report"><summary>Validation report <span>{report.issues?.length||0} issues</span></summary><p>Integrity check: <b>{report.integrityCheck}</b></p>{report.issues?.map((x:any,i:number)=><div className={`issue ${x.level}`} key={i}><b>{x.level}</b>{x.message}</div>)}</details>}
function DisplayConfigurationPage(){
 const[sections,setSections]=useState<any[]>([]),[fields,setFields]=useState<any[]>([]),[referenceDisplays,setReferenceDisplays]=useState<any>({actuators:[],brackets:[]}),[dragging,setDragging]=useState<{kind:'section'|'field';id:number}|null>(null),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');
 useEffect(()=>{Promise.all([api('/admin/display-sections'),api('/admin/display-fields'),api('/admin/reference-display')]).then(([sectionRows,fieldRows,references])=>{setSections(sectionRows);setFields(fieldRows);setReferenceDisplays(references)}).catch(e=>setError(e.message))},[]);
 const updateSection=(id:number,key:string,value:any)=>setSections(rows=>rows.map(row=>row.id===id?{...row,[key]:value}:row));
 const updateField=(id:number,key:string,value:any)=>setFields(rows=>rows.map(row=>row.id===id?{...row,[key]:value}:row));
 const moveSection=(targetId:number)=>{if(dragging?.kind!=='section'||dragging.id===targetId)return;setSections(rows=>{const moving=rows.find(row=>row.id===dragging.id);if(!moving)return rows;const remaining=rows.filter(row=>row.id!==dragging.id),index=remaining.findIndex(row=>row.id===targetId);remaining.splice(index,0,moving);return remaining})};
 const moveField=(sectionKey:string,targetId?:number)=>{if(dragging?.kind!=='field'||targetId===dragging.id)return;setFields(rows=>{const moving=rows.find(row=>row.id===dragging.id);if(!moving)return rows;const groups=new Map<string,any[]>();for(const section of sections)groups.set(section.section_key,[]);for(const row of rows.filter(row=>row.id!==moving.id)){if(!groups.has(row.section_key))groups.set(row.section_key,[]);groups.get(row.section_key)!.push(row)}const target=groups.get(sectionKey)||[];const index=targetId?target.findIndex(row=>row.id===targetId):target.length;target.splice(index<0?target.length:index,0,{...moving,section_key:sectionKey});groups.set(sectionKey,target);return sections.flatMap(section=>groups.get(section.section_key)||[])})};
 const save=async()=>{setBusy(true);setError('');setMessage('');const normalizedSections=sections.map((section,index)=>({...section,sort_order:(index+1)*10,is_visible:!!section.is_visible}));const normalize=(rows:any[])=>rows.map((field,index)=>({...field,sort_order:(index+1)*10,is_visible:!!field.is_visible,is_highlighted:!!field.is_highlighted,unit:field.unit||null,decimal_places:field.decimal_places===''||field.decimal_places===null||field.decimal_places===undefined?null:Number(field.decimal_places),help_text:field.help_text||null}));const normalizedFields=normalizedSections.flatMap(section=>normalize(fields.filter(field=>field.section_key===section.section_key)));const normalizedReferences={actuators:normalize(referenceDisplays.actuators),brackets:normalize(referenceDisplays.brackets)};try{await api('/admin/display-config',{method:'PUT',body:JSON.stringify({sections:normalizedSections,fields:normalizedFields,referenceDisplays:normalizedReferences})});setSections(normalizedSections);setFields(normalizedFields);setReferenceDisplays(normalizedReferences);setMessage('All display settings saved.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 return <><section className="intro"><div><span className="eyebrow">Presentation layer</span><h2>Display configuration</h2><p>Drag sections and fields into the order you want. Changes for valves, actuators, and brackets are committed together.</p></div><button className="primary compact" disabled={busy||!sections.length} onClick={save}>{busy?'Saving everything…':'Save all changes'}</button></section>{error&&<Notice type="error">{error}</Notice>}{message&&<div className="save-success">{message}</div>}<div className="drag-tip"><GripVertical size={17}/><span>Use the dotted handles to drag. Numeric order values are managed automatically.</span></div><div className="display-builder">{sections.map(section=>{const sectionFields=fields.filter(field=>field.section_key===section.section_key);return <section className={`card display-editor ${dragging?.kind==='section'&&dragging.id===section.id?'is-dragging':''}`} key={section.id} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();dragging?.kind==='section'?moveSection(section.id):moveField(section.section_key);setDragging(null)}}><div className="display-editor-head"><span className="drag-handle" draggable onDragStart={e=>{e.stopPropagation();setDragging({kind:'section',id:section.id});e.dataTransfer.effectAllowed='move'}} onDragEnd={()=>setDragging(null)} title="Drag section"><GripVertical/></span><input className="section-name" value={section.label} onChange={e=>updateSection(section.id,'label',e.target.value)}/><label className="check"><input type="checkbox" checked={!!section.is_visible} onChange={e=>updateSection(section.id,'is_visible',e.target.checked)}/>Show section</label><span className="field-count">{sectionFields.length} fields</span></div><div className="field-builder">{sectionFields.map(field=><div className={`field-editor ${dragging?.kind==='field'&&dragging.id===field.id?'is-dragging':''}`} key={field.id} onDragOver={e=>{e.preventDefault();e.stopPropagation()}} onDrop={e=>{e.preventDefault();e.stopPropagation();moveField(section.section_key,field.id);setDragging(null)}}><span className="drag-handle field-handle" draggable onDragStart={e=>{e.stopPropagation();setDragging({kind:'field',id:field.id});e.dataTransfer.effectAllowed='move'}} onDragEnd={()=>setDragging(null)} title="Drag field"><GripVertical/></span><div className="field-main"><code>{field.field_key}</code><input aria-label="Field label" value={field.label} onChange={e=>updateField(field.id,'label',e.target.value)}/></div><label>Unit<input value={field.unit||''} onChange={e=>updateField(field.id,'unit',e.target.value)}/></label><label>Decimals<input className="small-input" type="number" min="0" max="10" value={field.decimal_places??''} onChange={e=>updateField(field.id,'decimal_places',e.target.value)}/></label><label className="check"><input type="checkbox" checked={!!field.is_visible} onChange={e=>updateField(field.id,'is_visible',e.target.checked)}/>Show</label><label className="check"><input type="checkbox" checked={!!field.is_highlighted} onChange={e=>updateField(field.id,'is_highlighted',e.target.checked)}/>Highlight</label><label className="help-input">Help text<input value={field.help_text||''} onChange={e=>updateField(field.id,'help_text',e.target.value)}/></label></div>)}{!sectionFields.length&&<div className="field-drop-zone">Drop fields here</div>}</div></section>})}</div><ReferenceDisplayEditor title="Actuators page" fields={referenceDisplays.actuators} onChange={rows=>setReferenceDisplays((all:any)=>({...all,actuators:rows}))}/><ReferenceDisplayEditor title="Brackets page" fields={referenceDisplays.brackets} onChange={rows=>setReferenceDisplays((all:any)=>({...all,brackets:rows}))}/><div className="sticky-save"><span>{message||'Changes remain in this browser until saved.'}</span><button className="primary compact" disabled={busy||!sections.length} onClick={save}>{busy?'Saving…':'Save all changes'}</button></div></>
}
function ReferenceDisplayEditor({title,fields,onChange}:{title:string;fields:any[];onChange:(rows:any[])=>void}){const[dragging,setDragging]=useState<string|null>(null);const update=(key:string,name:string,value:any)=>onChange(fields.map(field=>field.field_key===key?{...field,[name]:value}:field));const move=(target:string)=>{if(!dragging||dragging===target)return;const moving=fields.find(field=>field.field_key===dragging);if(!moving)return;const remaining=fields.filter(field=>field.field_key!==dragging),index=remaining.findIndex(field=>field.field_key===target);remaining.splice(index,0,moving);onChange(remaining)};return <section className="card display-editor reference-display-editor"><div className="display-editor-head"><h3>{title}</h3><span className="field-count">{fields.length} fields</span></div><div className="field-builder">{fields.map(field=><div className={`field-editor ${dragging===field.field_key?'is-dragging':''}`} key={field.field_key} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();move(field.field_key);setDragging(null)}}><span className="drag-handle field-handle" draggable onDragStart={()=>setDragging(field.field_key)} onDragEnd={()=>setDragging(null)}><GripVertical/></span><div className="field-main"><code>{field.field_key}</code><input value={field.label} onChange={e=>update(field.field_key,'label',e.target.value)}/></div><label>Unit<input value={field.unit||''} onChange={e=>update(field.field_key,'unit',e.target.value)}/></label><label>Decimals<input className="small-input" type="number" min="0" max="10" value={field.decimal_places??''} onChange={e=>update(field.field_key,'decimal_places',e.target.value)}/></label><label className="check"><input type="checkbox" checked={!!field.is_visible} onChange={e=>update(field.field_key,'is_visible',e.target.checked)}/>Show</label><label className="check"><input type="checkbox" checked={!!field.is_highlighted} onChange={e=>update(field.field_key,'is_highlighted',e.target.checked)}/>Highlight</label><label className="help-input">Help text<input value={field.help_text||''} onChange={e=>update(field.field_key,'help_text',e.target.value)}/></label></div>)}</div></section>}
function DisplayConfig(){const[sections,setSections]=useState<any[]>([]),[fields,setFields]=useState<any[]>([]),[saved,setSaved]=useState('');const load=()=>Promise.all([api('/admin/display-sections'),api('/admin/display-fields')]).then(([a,b])=>{setSections(a);setFields(b)});useEffect(()=>{load()},[]);const saveSection=async(s:any)=>{await api(`/admin/display-sections/${s.id}`,{method:'PUT',body:JSON.stringify({...s,is_visible:!!s.is_visible})});setSaved('Section saved')};const saveField=async(f:any)=>{await api(`/admin/display-fields/${f.id}`,{method:'PUT',body:JSON.stringify({...f,is_visible:!!f.is_visible,is_highlighted:!!f.is_highlighted,unit:f.unit||null,decimal_places:f.decimal_places===''?null:Number(f.decimal_places),help_text:f.help_text||null})});setSaved('Field saved')};const change=(id:number,k:string,v:any)=>setFields(x=>x.map(f=>f.id===id?{...f,[k]:v}:f));return <><section className="intro"><div><span className="eyebrow">Presentation layer</span><h2>Display configuration</h2><p>Rename, group, order, format, and highlight known fields without changing source schemas.</p></div>{saved&&<span className="saved">{saved}</span>}</section><section className="card"><div className="section-title"><h3>Sections</h3></div><div className="config-list">{sections.map((s,i)=><div className="config-row" key={s.id}><input value={s.label} onChange={e=>setSections(a=>a.map(x=>x.id===s.id?{...x,label:e.target.value}:x))}/><input className="tiny" type="number" value={s.sort_order} onChange={e=>setSections(a=>a.map(x=>x.id===s.id?{...x,sort_order:Number(e.target.value)}:x))}/><label className="check"><input type="checkbox" checked={!!s.is_visible} onChange={e=>setSections(a=>a.map(x=>x.id===s.id?{...x,is_visible:e.target.checked}:x))}/>Visible</label><button onClick={()=>saveSection(sections[i])}>Save</button></div>)}</div></section><section className="card table-card"><div className="section-title"><h3>Fields</h3><span>{fields.length} known fields</span></div><div className="table-wrap"><table className="config-table"><thead><tr><th>Field key</th><th>Label</th><th>Section</th><th>Order</th><th>Unit</th><th>Decimals</th><th>Show</th><th>Highlight</th><th>Help text</th><th/></tr></thead><tbody>{fields.map(f=><tr key={f.id}><td><code>{f.field_key}</code></td><td><input value={f.label} onChange={e=>change(f.id,'label',e.target.value)}/></td><td><select value={f.section_key} onChange={e=>change(f.id,'section_key',e.target.value)}>{sections.map(s=><option key={s.section_key}>{s.section_key}</option>)}</select></td><td><input className="tiny" type="number" value={f.sort_order} onChange={e=>change(f.id,'sort_order',Number(e.target.value))}/></td><td><input className="tiny" value={f.unit||''} onChange={e=>change(f.id,'unit',e.target.value)}/></td><td><input className="tiny" type="number" value={f.decimal_places??''} onChange={e=>change(f.id,'decimal_places',e.target.value)}/></td><td><input type="checkbox" checked={!!f.is_visible} onChange={e=>change(f.id,'is_visible',e.target.checked)}/></td><td><input type="checkbox" checked={!!f.is_highlighted} onChange={e=>change(f.id,'is_highlighted',e.target.checked)}/></td><td><input value={f.help_text||''} onChange={e=>change(f.id,'help_text',e.target.value)}/></td><td><button onClick={()=>saveField(f)}>Save</button></td></tr>)}</tbody></table></div><div className="preview-link"><a className="button" href="/valves">Preview in valve viewer</a></div></section></>}
function UsersPage(){const[users,setUsers]=useState<any[]>([]),[show,setShow]=useState(false),[form,setForm]=useState({username:'',password:'',role:'user'}),[error,setError]=useState('');const load=()=>api('/admin/users').then(setUsers).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const create=async(e:React.FormEvent)=>{e.preventDefault();try{await api('/admin/users',{method:'POST',body:JSON.stringify(form)});setShow(false);setForm({username:'',password:'',role:'user'});load()}catch(e){setError((e as Error).message)}};const update=async(u:any)=>{try{await api(`/admin/users/${u.id}`,{method:'PUT',body:JSON.stringify({role:u.role,is_active:!!u.is_active})});load()}catch(e){setError((e as Error).message)}};const reset=async(u:any)=>{const password=window.prompt(`New password for ${u.username} (6+ characters)`);if(password)try{await api(`/admin/users/${u.id}/reset-password`,{method:'POST',body:JSON.stringify({password})});alert('Password reset')}catch(e){alert((e as Error).message)}};return <><section className="intro"><div><span className="eyebrow">Supabase accounts</span><h2>User management</h2><p>Control viewer, administrator, and uploader access.</p></div><button className="primary compact" onClick={()=>setShow(!show)}>Add user</button></section>{error&&<Notice type="error">{error}</Notice>}{show&&<form className="card inline-form" onSubmit={create}>{error&&<Notice type="error">{error}</Notice>}<label>Email<input type="email" required value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Initial password<input type="password" minLength={6} value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/></label><label>Role<select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="user">User</option><option value="admin">Admin</option><option value="uploader">Uploader</option></select></label><button className="primary">Create user</button></form>}<section className="card table-card"><div className="table-wrap"><table><thead><tr><th>Email</th><th>Role</th><th>Status</th><th>Last login</th><th>Created</th><th/></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><strong>{u.username}</strong></td><td><select value={u.role} onChange={e=>setUsers(a=>a.map(x=>x.id===u.id?{...x,role:e.target.value}:x))}><option>user</option><option>admin</option><option>uploader</option></select></td><td><label className="check"><input type="checkbox" checked={!!u.is_active} onChange={e=>setUsers(a=>a.map(x=>x.id===u.id?{...x,is_active:e.target.checked}:x))}/>{u.is_active?'Active':'Inactive'}</label></td><td>{formatTimestamp(u.last_login_at)||'Never'}</td><td>{formatTimestamp(u.created_at)}</td><td className="actions"><button onClick={()=>update(u)}>Save</button><button onClick={()=>reset(u)}>Reset password</button></td></tr>)}</tbody></table></div></section></>}
function AuditLog(){const[rows,setRows]=useState<any[]>([]);useEffect(()=>{api('/admin/audit-logs?limit=200').then(setRows)},[]);return <section className="card table-card"><div className="section-title"><h3>Audit events</h3><span>Latest 200</span></div><div className="table-wrap"><table><thead><tr><th>Timestamp</th><th>User</th><th>Action</th><th>Entity</th><th>Details</th><th>IP address</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{formatTimestamp(r.created_at)}</td><td>{r.username||'System'}</td><td><code>{r.action}</code></td><td>{r.entity_type||'—'} {r.entity_id}</td><td className="details-cell">{r.details||'—'}</td><td>{r.ip_address||'—'}</td></tr>)}</tbody></table></div></section>}
function ReferencePage({type}:{type:'actuator-sets'|'bracket-patterns'|'universal-adapters'}){const[rows,setRows]=useState<any[]>([]),[config,setConfig]=useState<any[]>([]),[error,setError]=useState('');useEffect(()=>{const page=type==='actuator-sets'?'actuators':type==='bracket-patterns'?'brackets':null;Promise.all([api(`/admin/${type}`),page?api(`/reference-display?type=${page}`):Promise.resolve([])]).then(([data,display])=>{setRows(data as any[]);setConfig(display as any[])}).catch(e=>setError(e.message))},[type]);if(error)return <Notice type="error">{error}</Notice>;const title={'actuator-sets':'Actuators','bracket-patterns':'Brackets','universal-adapters':'Universal adapters'}[type],cards=type!=='universal-adapters';return <section className="card table-card reference-page"><div className="section-title"><h3>{title}</h3><span>{rows.length} records</span></div>{!rows.length?<div className="empty-small">No reference records found.</div>:cards?<div className="reference-cards">{rows.map((row:any)=>{const actuator=type==='actuator-sets',id=actuator?row.actuator_id:row.bracket_id,name=actuator?(row.actuator_name||`Actuator ${id}`):(row.bracket_code||`Bracket ${id}`),meta=actuator?[row.theme_name,present(row.square_size)?`Square ${row.square_size}`:null].filter(present).join(' · '):[present(row.part_number)?`Part # ${row.part_number}`:null,`Bracket ID ${id}`].filter(present).join(' · ');return <details key={id}><summary><span className={`reference-icon ${actuator?'actuator':'bracket'}`}>{actuator?<Gauge/>:<Boxes/>}</span><span className="reference-summary"><strong>{name}</strong><small>{meta||`ID ${id}`}</small></span><span className="reference-id">#{id}</span><ChevronDown className="reference-chevron"/></summary><GroupedRecord row={row} config={config} type={actuator?'actuator':'bracket'}/></details>})}</div>:<RecordTable rows={rows} config={config}/>}</section>}
function PopularList({title,rows}:any){return <section className="card popular-card"><div className="section-title"><h3>{title}</h3><span>Top {rows.length}</span></div><ol>{rows.map((row:any,index:number)=><li key={`${row.label}-${index}`}><b>{index+1}</b><span title={row.label}>{row.label}</span><small>{row.runs} {row.runs===1?'job':'jobs'} · {Number(row.quantity||0)} total units</small></li>)}</ol></section>}
function ManufacturingExplorer(){const[data,setData]=useState<any>(),[query,setQuery]=useState(''),[brand,setBrand]=useState(''),[actuator,setActuator]=useState(''),[from,setFrom]=useState(''),[to,setTo]=useState(''),[popularCount,setPopularCount]=useState(5),[popularBy,setPopularBy]=useState<'jobs'|'quantity'>('jobs'),[expanded,setExpanded]=useState<number|null>(null),[error,setError]=useState('');useEffect(()=>{api('/manufacturing/explorer').then(setData).catch(e=>setError(e.message))},[]);if(error)return <Notice type="error">{error}</Notice>;if(!data)return <Splash/>;const searchable=['job_number','valve_id','valve_brand','valve_size','valve_class','valve_model','valve_port','actuator_name','configuration_name','fusion_document_name','bracket_code'],needle=query.trim().toLowerCase(),records=data.records.filter((row:any)=>{const date=String(row.timestamp??'').slice(0,10);return(!brand||row.valve_brand===brand)&&(!actuator||String(row.actuator_name)===actuator)&&(!from||date>=from)&&(!to||date<=to)&&(!needle||searchable.some(key=>String(row[key]??'').toLowerCase().includes(needle)))}),rank=(keys:string[])=>{const totals=new Map<string,{label:string,runs:number,quantity:number}>();records.forEach((row:any)=>{const values=keys.map(key=>String(row[key]??'').trim());if(values.some(value=>!value))return;const label=values.join(' · '),current=totals.get(label)??{label,runs:0,quantity:0};current.runs++;current.quantity+=Math.max(0,Number(row.quantity)||0);totals.set(label,current)});return[...totals.values()].sort((a,b)=>popularBy==='quantity'?b.quantity-a.quantity||b.runs-a.runs:b.runs-a.runs||b.quantity-a.quantity).slice(0,popularCount)},clear=()=>{setQuery('');setBrand('');setActuator('');setFrom('');setTo('')};return <><section className="intro"><div><span className="eyebrow">Manufacturing history</span><h2>Manufacturing Database</h2><p>Search past jobs and see which valve, actuator, and hardware combinations are used most often.</p></div></section><section className="card manufacturing-search"><label className="manufacturing-query"><span><Search/>Search jobs and hardware</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Job number, valve, bracket…"/></label><label>Valve brand<select value={brand} onChange={e=>setBrand(e.target.value)}><option value="">All brands</option>{data.filters.brands.map((value:string)=><option key={value}>{value}</option>)}</select></label><label>Actuator<select value={actuator} onChange={e=>setActuator(e.target.value)}><option value="">All actuators</option>{data.filters.actuators.map((value:string)=><option key={value}>{value}</option>)}</select></label><label>From date<input type="date" value={from} max={to||undefined} onChange={e=>setFrom(e.target.value)}/></label><label>To date<input type="date" value={to} min={from||undefined} onChange={e=>setTo(e.target.value)}/></label><button className="button" onClick={clear}>Clear filters</button></section><details className="card popularity-panel"><summary><span><Activity/>Popular hardware</span><small>Based on the {records.length} filtered records</small><ChevronDown/></summary><div className="popularity-controls"><label>Rank by<select value={popularBy} onChange={e=>setPopularBy(e.target.value as 'jobs'|'quantity')}><option value="jobs">Number of jobs</option><option value="quantity">Total quantity</option></select></label><label>Results per list<select value={popularCount} onChange={e=>setPopularCount(Number(e.target.value))}><option>3</option><option>5</option><option>8</option><option>10</option><option>15</option></select></label></div><div className="manufacturing-insights"><PopularList title="Popular valves" rows={rank(['valve_brand','valve_size','valve_class','valve_model'])}/><PopularList title="Popular actuators" rows={rank(['actuator_name'])}/><PopularList title="Popular brackets" rows={rank(['bracket_code'])}/></div></details><section className="card table-card manufacturing-results"><div className="section-title"><h3>Manufacturing records</h3><span>{records.length} of {data.records.length}</span></div><div className="table-wrap"><table><thead><tr><th/><th>Drawing created</th><th>Job number</th><th>Qty</th><th>Valve</th><th>Actuator</th><th>Configuration</th><th>Bracket</th></tr></thead><tbody>{records.map((row:any)=><React.Fragment key={row.id}><tr className="clickable-row" onClick={()=>setExpanded(expanded===row.id?null:row.id)}><td>{expanded===row.id?<ChevronDown/>:<ChevronRight/>}</td><td>{formatTimestamp(row.timestamp)}</td><td><strong>{row.job_number||'—'}</strong></td><td>{row.quantity||'—'}</td><td>{[row.valve_brand,row.valve_size,row.valve_class,row.valve_model].filter(present).join(' · ')||'—'}</td><td>{row.actuator_name||'—'}</td><td>{row.configuration_name||'—'}</td><td>{row.bracket_code||'—'}</td></tr>{expanded===row.id&&<tr className="expanded-row"><td colSpan={8}><dl className="parameter-grid">{Object.entries(row).filter(([,value])=>present(value)).map(([key,value])=><div key={key}><dt>{friendly(key)}</dt><dd>{String(value)}</dd></div>)}</dl></td></tr>}</React.Fragment>)}</tbody></table></div>{!records.length&&<div className="empty-small">No manufacturing records match these filters.</div>}</section></>}
function configuredFields(row:any,config:any[]){return (config.length?config:Object.keys(row).map((field_key,index)=>({field_key,label:friendly(field_key),sort_order:index,is_visible:1}))).filter(field=>field.is_visible).sort((a,b)=>a.sort_order-b.sort_order)}
function displayValue(row:any,field:any){let value=row[field.field_key];if(typeof value==='number'&&field.decimal_places!=null)value=value.toFixed(field.decimal_places);return `${value}${field.unit?` ${field.unit}`:''}`}
function GroupedRecord({row,config,type}:any){const configured=configuredFields(row,config),fields=[...configured,...(!configured.some(field=>field.field_key==='part_number')&&present(row.part_number)?[{field_key:'part_number',label:'Part number',sort_order:-1,is_visible:1,is_highlighted:1}]:[])].filter(field=>present(row[field.field_key])),groups:any=type==='actuator'?{'Identification':['actuator_id','actuator_name','theme_name'],'Stem and square':['square_size','square_height','sq_rad','d_stem'],'Mounting pattern':['actuator_hole_dia','actuator_bhc','actuator_hole_qty','actuator_start_angle'],'Bracket':['bracket_height']}:{'Identification':['bracket_id','bracket_code','part_number'],'Actuator pattern 1':'actuator_1_','Actuator pattern 2':'actuator_2_','Actuator pattern 3':'actuator_3_','Valve pattern 1':['valve_bhc','valve_hole_dia','valve_hole_qty','valve_start_angle'],'Valve pattern 2':'valve_2_','Valve pattern 3':'valve_3_','Packing flange':'packing_','Grid and offsets':['grid','offset'],'Bracket dimensions':['bracket_width','bracket_length','bracket_height','center_hole']};return <div className={`grouped ${type}`}>{Object.entries(groups).map(([name,match]:any)=>{const cells=fields.filter(field=>Array.isArray(match)?match.some((key:string)=>field.field_key===key||field.field_key.includes(key)):field.field_key.startsWith(match));return cells.length?<div className="reference-group" key={name}><h4>{name}</h4><dl>{cells.map(field=><div className={field.is_highlighted?'reference-highlight':''} key={field.field_key} title={field.help_text||''}><dt>{field.label}</dt><dd>{displayValue(row,field)}</dd></div>)}</dl></div>:null})}</div>}
function RecordTable({rows,config=[]}:any){const cols=configuredFields(Object.assign({},...rows),config).filter(field=>rows.some((row:any)=>present(row[field.field_key])));return <div className="table-wrap"><table><thead><tr>{cols.map(field=><th className={field.is_highlighted?'reference-highlight':''} key={field.field_key}>{field.label}</th>)}</tr></thead><tbody>{rows.map((row:any,index:number)=><tr key={index}>{cols.map(field=><td className={field.is_highlighted?'reference-highlight':''} key={field.field_key}>{present(row[field.field_key])?displayValue(row,field):''}</td>)}</tr>)}</tbody></table></div>}
function Notice({children,type}:{children:React.ReactNode;type:'error'|'warning'}){return <div className={`notice ${type}`}>{children}</div>}function Splash(){return <div className="splash"><div className="spinner"/>Loading…</div>}const formatBytes=(n:number)=>n?`${(n/1024/1024).toFixed(1)} MB`:'—';
function present(value:any){return value!==null&&value!==undefined&&!(typeof value==='string'&&value.trim()==='')}
document.addEventListener('click',event=>{const target=event.target as Element|null,anchor=target?.closest('a[href="/valves"]');if(anchor){event.preventDefault();window.location.hash='/valves'}});

function App(){return <AuthProvider><HashRouter><Routes><Route path="/login" element={<Login/>}/><Route element={<Protected/>}><Route element={<Shell/>}><Route path="/configurator" element={<Navigate to="/valves" replace/>}/><Route path="/valves" element={<ValveSelector/>}/><Route path="/valves/:id" element={<ValveDetail/>}/><Route path="/manufacturing" element={<ManufacturingExplorer/>}/><Route path="/actuators" element={<ReferencePage type="actuator-sets"/>}/><Route path="/brackets" element={<ReferencePage type="bracket-patterns"/>}/><Route element={<Protected admin/>}><Route path="/admin" element={<Dashboard/>}/><Route path="/admin/databases" element={<Databases/>}/><Route path="/admin/display" element={<DisplayConfigurationPage/>}/><Route path="/admin/users" element={<UsersPage/>}/><Route path="/admin/audit-log" element={<AuditLog/>}/><Route path="/admin/actuators" element={<Navigate to="/actuators" replace/>}/><Route path="/admin/brackets" element={<Navigate to="/brackets" replace/>}/><Route path="/admin/universal-adapters" element={<ReferencePage type="universal-adapters"/>}/></Route></Route></Route><Route path="*" element={<Navigate to="/valves"/>}/></Routes></HashRouter></AuthProvider>};createRoot(document.getElementById('root')!).render(<App/>);
